export const readStoredTheme = (storageOwner, key, allowedThemes) => {
  try {
    const storage = storageOwner.localStorage;
    const theme = storage.getItem(key);
    return allowedThemes.has(theme) ? theme : null;
  } catch (_error) {
    return null;
  }
};

export const writeStoredTheme = (storageOwner, key, theme) => {
  try {
    const storage = storageOwner.localStorage;
    if (theme === "system") storage.removeItem(key);
    else storage.setItem(key, theme);
  } catch (_error) {
    // Theme selection still applies to the current document.
  }
};

export const readStoredBoolean = (storageOwner, key) => {
  try {
    return storageOwner.localStorage.getItem(key) === "true";
  } catch (_error) {
    return false;
  }
};

export const writeStoredBoolean = (storageOwner, key, value) => {
  try {
    const storage = storageOwner.localStorage;
    if (value) storage.setItem(key, "true");
    else storage.removeItem(key);
  } catch (_error) {
    // Browser storage can be unavailable in restricted embedding contexts.
  }
};

export const focusShortcutAction = (event, focusActive) => {
  const interactive = event.target?.closest?.(
    "a[href], button, input, textarea, select, [contenteditable='true'], [role='button']"
  );

  if (event.isComposing || event.repeat || event.altKey || event.ctrlKey || event.metaKey) {
    return null;
  }

  if (event.key === "Escape" && focusActive) return "exit";
  if (interactive) return null;
  if (event.key?.toLowerCase() === "f") return "toggle";
  return null;
};

export const readStoredBranchStates = (storageOwner, key) => {
  try {
    const storage = storageOwner.localStorage;
    const value = JSON.parse(storage.getItem(key) || "[]");
    if (!Array.isArray(value)) return [];

    return value
      .filter(entry =>
        Array.isArray(entry) &&
        typeof entry[0] === "string" &&
        entry[0].length <= 200 &&
        typeof entry[1] === "boolean"
      )
      .slice(-200);
  } catch (_error) {
    return [];
  }
};

export const writeStoredBranchStates = (storageOwner, key, states) => {
  try {
    const storage = storageOwner.localStorage;
    storage.setItem(key, JSON.stringify(Array.from(states).slice(-200)));
  } catch (_error) {
    // Disclosure state remains available for the current document.
  }
};

export const chartHeadline = (series, unit, formatter) => {
  const latest = series.flatMap(item => {
    const points = Array.isArray(item.points) ? item.points : [];
    return points.length ? [{ label: item.label, point: points.at(-1) }] : [];
  });
  if (!latest.length) return "No data";
  if (latest.length === 1) return formatter(latest[0].point[1], unit);
  if (latest.length === 2) {
    return latest
      .map(item => `${item.label} ${formatter(item.point[1], unit)}`)
      .join(" · ");
  }
  return `${latest.length} series`;
};

export const formatChartValue = (value, unit) => {
  if (!Number.isFinite(value)) return "—";
  if (unit === "bytes" || unit === "bytes/s") {
    const absolute = Math.abs(value);
    const suffix = unit === "bytes/s" ? "/s" : "";
    if (absolute >= 1048576) return `${(value / 1048576).toFixed(1)} MB${suffix}`;
    if (absolute >= 1024) return `${(value / 1024).toFixed(1)} KB${suffix}`;
    return `${Math.round(value)} B${suffix}`;
  }
  if (unit === "reductions/s") return `${Math.round(value).toLocaleString()} /s`;
  if (unit === "ms") return `${Math.round(value)} ms`;
  if (unit === "%") return `${value.toFixed(1)}%`;
  return Number.isInteger(value) ? value.toLocaleString() : value.toFixed(1);
};

export const chartDomain = (values, minimum, maximum, previousDomain = null) => {
  let lower = Number.isFinite(minimum) ? minimum : Math.min(...values);
  let upper = Number.isFinite(maximum) ? maximum : Math.max(...values);

  if (lower === upper) {
    const padding = Math.max(Math.abs(lower) * 0.08, 1);
    lower -= padding;
    upper += padding;
  }

  if (Array.isArray(previousDomain) && previousDomain.length === 2) {
    const fixedMinimum = Number.isFinite(minimum);
    const fixedMaximum = Number.isFinite(maximum);
    const expands = lower < previousDomain[0] || upper > previousDomain[1];
    const previousSpan = previousDomain[1] - previousDomain[0];
    const currentSpan = upper - lower;
    const contracts = currentSpan <= previousSpan * 0.5;

    if (!expands && !contracts) return previousDomain;

    if (!expands && contracts) {
      const padding = Math.max(currentSpan * 0.1, 1);
      if (!fixedMinimum) lower -= padding;
      if (!fixedMaximum) upper += padding;
    } else {
      if (!fixedMinimum) lower = Math.min(lower, previousDomain[0]);
      if (!fixedMaximum) upper = Math.max(upper, previousDomain[1]);
    }
  }

  return [lower, upper];
};

export const graphUpdateMode = (sequence, focusChanged) => {
  return sequence > 0 && !focusChanged ? "patch" : "layout";
};

export const chartAriaLabel = title => `${title || "History"} history chart`;

export const graphOmissionLabel = (processCount, relationshipCount) => {
  const labels = [];

  if (processCount > 0) labels.push(`${processCount} processes`);
  if (relationshipCount > 0) labels.push(`${relationshipCount} relationships`);

  return labels.length > 0 ? `${labels.join(" · ")} omitted` : "";
};

const anchoredColumns = [0, -1, 1, -2, 2];

export const anchoredNodeOffset = index => ({
  x: anchoredColumns[index % anchoredColumns.length] * 148,
  y: 94 + Math.floor(index / 5) * 94
});

export const newNodePlacements = (edges, nodeIds, currentNodeIds) => {
  const existing = new Set(currentNodeIds);
  const known = new Set(existing);
  const pending = new Set(nodeIds);
  const placements = [];

  while (pending.size > 0) {
    const wave = Array.from(pending).flatMap(nodeId => {
      const incoming = edges.find(edge => edge.data.target === nodeId);

      if (incoming) {
        return known.has(incoming.data.source)
          ? [{ nodeId, anchorId: incoming.data.source }]
          : [];
      }

      const outgoing = edges.find(edge =>
        edge.data.source === nodeId && known.has(edge.data.target)
      );

      return [{ nodeId, anchorId: outgoing?.data.target || null }];
    });

    const ready = wave.length > 0
      ? wave
      : [{ nodeId: pending.values().next().value, anchorId: null }];

    ready.forEach(placement => {
      placements.push(placement);
      pending.delete(placement.nodeId);
      known.add(placement.nodeId);
    });
  }

  const anchorCounts = edges.reduce((counts, edge) => {
    if (existing.has(edge.data.source) && existing.has(edge.data.target)) {
      counts.set(edge.data.source, (counts.get(edge.data.source) || 0) + 1);
    }

    return counts;
  }, new Map());

  return placements.map(placement => {
    const ordinal = anchorCounts.get(placement.anchorId) || 0;
    anchorCounts.set(placement.anchorId, ordinal + 1);

    return { ...placement, offset: anchoredNodeOffset(ordinal) };
  });
};

export const revisionDecision = (
  currentEpoch,
  currentRevision,
  nextEpoch,
  nextRevision
) => {
  const reset = nextEpoch !== currentEpoch;
  return { reset, accept: reset || nextRevision >= currentRevision };
};
